// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(amount > 0 && amount <= address(this).balance);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        try c.migrateTo(actor) {} catch {}
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceBefore == balanceAfter);
    }
}
